class Solution {
public:
    int numberOfPoints(vector<vector<int>>& nums) {
        vector<bool> occ(105, false);
        for (const auto& p : nums) {
            for (int x = p[0]; x <= p[1]; x++) occ[x] = true;
        }
        int ans = 0;
        for (bool b : occ) if (b) ans++;
        return ans;
    }
};

