/**
 * @param {number[][]} nums
 * @return {number}
 */
var numberOfPoints = function(nums) {
    const occ = new Set();
    for (const [start, end] of nums) {
        for (let x = start; x <= end; x++) occ.add(x);
    }
    return occ.size;
};
